<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {api} from '../main'
import {useChart} from '../chart'
const datasets=ref([]),tasks=ref([]),selected=ref(null),message=ref(''),scatter=ref(),importance=ref()
const features=['duration','likes','comments','shares','favorites','hashtags','hot_bgm','category','publish_period']
const form=ref({datasetId:'',name:'',algorithm:'forest',target:'views',features:[...features],params:{testRatio:.2,seed:42,trees:100,maxDepth:8,learningRate:.1,iterations:100}})
const report=computed(()=>{try{return selected.value?.reportJson?JSON.parse(selected.value.reportJson):null}catch{return null}})
const scatterOption=computed(()=>({tooltip:{trigger:'item'},xAxis:{name:'真实值',type:'value'},yAxis:{name:'预测值',type:'value'},series:[{type:'scatter',data:(report.value?.actual||[]).map((v,i)=>[v,report.value.predicted[i]])}]}))
const importanceOption=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'value'},yAxis:{type:'category',data:(report.value?.importance||[]).map(x=>x.feature)},series:[{type:'bar',data:(report.value?.importance||[]).map(x=>x.importance)}]}))
useChart(scatter,scatterOption);useChart(importance,importanceOption)
async function load(){datasets.value=(await api.get('/datasets')).data;tasks.value=(await api.get('/models')).data.sort((a,b)=>b.id-a.id);if(selected.value)selected.value=tasks.value.find(x=>x.id===selected.value.id)||null}
async function train(){try{if(!form.value.features.length)throw Error('请至少选择一个特征');const r=await api.post('/train',form.value);selected.value=r.data;message.value='任务已提交，请等待训练结果';await load()}catch(e){message.value=e.response?.data?.error||e.message}}
let timer;onMounted(async()=>{await load();timer=setInterval(load,3000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="panel"><h2>创建训练任务</h2><div class="form"><label>数据集<select v-model="form.datasetId"><option value="">请选择</option><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}}（{{d.samples}}条）</option></select></label><label>模型名称<input v-model="form.name" placeholder="可选"></label><label>算法<select v-model="form.algorithm"><option value="linear">线性回归</option><option value="forest">随机森林</option><option value="xgboost">XGBoost</option><option value="lightgbm">LightGBM</option></select></label><label>预测目标<select v-model="form.target"><option value="views">播放量</option><option value="hot_score">综合热度分</option></select></label></div><h3>输入特征</h3><div class="chips"><label v-for="f in features" :key="f"><input type="checkbox" :value="f" v-model="form.features"> {{f}}</label></div><h3>训练参数</h3><div class="form"><label>测试集比例<input type="number" v-model.number="form.params.testRatio" min=".1" max=".4" step=".05"></label><label>随机种子<input type="number" v-model.number="form.params.seed"></label><label v-if="form.algorithm==='forest'">树数量<input type="number" v-model.number="form.params.trees" min="10"></label><label v-if="form.algorithm==='forest'">最大深度<input type="number" v-model.number="form.params.maxDepth" min="1"></label><label v-if="['xgboost','lightgbm'].includes(form.algorithm)">学习率<input type="number" v-model.number="form.params.learningRate" min=".01" max="1" step=".01"></label><label v-if="['xgboost','lightgbm'].includes(form.algorithm)">迭代次数<input type="number" v-model.number="form.params.iterations" min="10"></label></div><button :disabled="!form.datasetId" @click="train">开始训练</button><p v-if="message" class="message">{{message}}</p></section><section class="panel" style="margin-top:16px"><h2>训练任务历史</h2><table><tr><th>名称</th><th>算法</th><th>目标</th><th>状态</th><th>MAE</th><th>R²</th><th>查看</th></tr><tr v-for="t in tasks" :key="t.id"><td>{{t.name}}</td><td>{{t.algorithm}}</td><td>{{t.target}}</td><td>{{t.status}}</td><td>{{t.status==='训练成功'?t.mae.toFixed(2):'—'}}</td><td>{{t.status==='训练成功'?t.r2.toFixed(3):'—'}}</td><td><button class="secondary" @click="selected=t">详情</button></td></tr></table></section><div v-if="selected" class="panels"><section class="panel wide"><h2>{{selected.name}} · {{selected.status}}</h2><p v-if="selected.error" class="message error">{{selected.error}}</p><p v-if="report">MAE <span class="metric">{{selected.mae.toFixed(2)}}</span>　 MSE <span class="metric">{{selected.mse.toFixed(2)}}</span>　 R² <span class="metric">{{selected.r2.toFixed(3)}}</span>　训练样本 {{report.trainCount}}　测试样本 {{report.testCount}}</p><p>模型文件：{{selected.modelPath||'等待生成'}}</p></section><section class="panel"><h2>真实值与预测值</h2><div ref="scatter" class="chart"></div></section><section class="panel"><h2>特征重要性</h2><div ref="importance" class="chart"></div></section></div></template>
